import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int arr[][] = new int[6][6];

        // Input for the 6x6 matrix
        for (int i = 0; i < 6; i++) {
            for (int j = 0; j < 6; j++) {
                arr[i][j] = in.nextInt();
            }
        }

        int sum, maxSum = Integer.MIN_VALUE;

        // Calculate hourglass sum and find the maximum
        for (int i = 0; i < 6; i++) {
            for (int j = 0; j < 6; j++) {
                if ((i + 2) < 6 && (j + 2) < 6) {
                    sum = arr[i][j] + arr[i][j + 1] + arr[i][j + 2]
                        + arr[i + 1][j + 1]
                        + arr[i + 2][j] + arr[i + 2][j + 1] + arr[i + 2][j + 2];

                    if (sum > maxSum) {
                        maxSum = sum;
                    }
                }
            }
        }

        // Reduce maxSum to a single digit
        int result = reduceToSingleDigit(maxSum);

        // Print the final single-digit result
        System.out.println(result);
    }

    // Function to reduce a number to a single digit
    private static int reduceToSingleDigit(int num) {
        while (num >= 10) {
            int tempSum = 0;
            while (num > 0) {
                tempSum += num % 10;
                num /= 10;
            }
            num = tempSum;
        }
        return num;
    }
}

